//! `ServerRecipeBook` against the real vanilla class (fixture generated by `scripts/golden-recipes.sh` from
//! `fixtures/RecipeBookGolden.java`): `recipe_book_add` / `recipe_book_remove` / `recipe_book_settings` packets byte for byte,
//! the known/highlight sets after add, remove, seen-recipe, settings changes and the initial book.

use crate::common;

use std::io::Read;

use mc_core::ident::Identifier;
use mc_game::world::item::crafting::*;
use mc_protocol::packets::play::inventory::{
    ClientboundRecipeBookAddPacket, RecipeBookType, RecipeDisplayId,
};
use mc_protocol::{Decode, Encode};
use mc_world::level_storage::WorldDataConfiguration;

fn hex<T: Encode>(value: &T) -> String {
    let mut out = Vec::new();
    value.encode(&mut out);
    out.iter().map(|b| format!("{b:02x}")).collect()
}

fn unhex(s: &str) -> Vec<u8> {
    (0..s.len() / 2)
        .map(|i| u8::from_str_radix(&s[2 * i..2 * i + 2], 16).unwrap())
        .collect()
}

/// The `recipe_book_add` of the initial book lists the known recipes in an unspecified (identity hash) order: sort by display id.
fn normalized_add(hex_text: &str) -> String {
    let mut bytes = unhex(hex_text).as_slice().to_vec();
    let mut input: &[u8] = &bytes;
    let mut packet =
        ClientboundRecipeBookAddPacket::decode(&mut input).expect("decodable add packet");
    packet.entries.sort_by_key(|e| e.contents.id.index);
    bytes.clear();
    hex(&packet)
}

fn sorted_ids<'a>(ids: impl Iterator<Item = &'a Identifier>) -> String {
    let mut v: Vec<String> = ids.map(Identifier::to_string).collect();
    v.sort();
    v.join(",")
}

#[test]
fn recipe_book_matches_vanilla() {
    let _s = common::SERIAL.lock().unwrap_or_else(|e| e.into_inner());
    let dir = tempfile::tempdir().unwrap();
    let (_, stem) = common::load_world(
        &dir.path().join("world"),
        WorldDataConfiguration::DEFAULT,
        true,
    )
    .unwrap();
    let manager = stem
        .data_pack_resources
        .listener::<RecipeManager>()
        .expect("recipe manager")
        .clone();
    let mut text = String::new();
    flate2::read::GzDecoder::new(
        std::fs::File::open(concat!(
            env!("CARGO_MANIFEST_DIR"),
            "/tests/fixtures/recipe_book_golden.txt.gz"
        ))
        .unwrap(),
    )
    .read_to_string(&mut text)
    .unwrap();

    let mut book = ServerRecipeBook::new();
    let mut lines = text.lines().peekable();
    let (mut adds, mut removes) = (0, 0);
    let mut op_no = 0;
    while let Some(line) = lines.next() {
        let op = line.strip_prefix("OP ").expect("OP line");
        let mut expected: Vec<String> = Vec::new();
        while let Some(next) = lines.peek() {
            if next.starts_with("OP ") {
                break;
            }
            // the advancement trigger is not part of the book (it fires between the learn step and the packet)
            let l = lines
                .next()
                .unwrap()
                .strip_prefix("OUT ")
                .unwrap()
                .to_owned();
            if l != "TRIGGER" {
                expected.push(l);
            }
        }
        op_no += 1;
        let words: Vec<&str> = op.split(' ').collect();
        let mut events: Vec<String> = Vec::new();
        let holders = |ids: &str| -> Vec<RecipeHolder> {
            ids.split(',')
                .map(|id| {
                    manager
                        .by_key(&Identifier::parse(id).unwrap())
                        .expect("recipe")
                        .clone()
                })
                .collect()
        };
        match words[0] {
            "scenario" => {
                book = ServerRecipeBook::new();
                continue;
            }
            "add" => {
                let mut entries = Vec::new();
                for h in holders(words[1]) {
                    book.try_add_recipe(&h, &manager, &mut entries);
                }
                let count = entries.len();
                if let Some(p) = ServerRecipeBook::add_packet(entries) {
                    events.push(format!("PKT add {}", hex(&p)));
                    adds += 1;
                }
                events.push(format!("RET {count}"));
            }
            "remove" => {
                let (packet, count) = book.remove_recipes(&holders(words[1]), &manager);
                if let Some(p) = packet {
                    events.push(format!("PKT remove {}", hex(&p)));
                    removes += 1;
                }
                events.push(format!("RET {count}"));
            }
            "seen" => {
                if let Some(info) = manager.get_recipe_from_display(RecipeDisplayId {
                    index: words[1].parse().unwrap(),
                }) {
                    book.remove_highlight(&info.parent.id);
                }
            }
            "settings" => {
                let ty = [
                    RecipeBookType::Crafting,
                    RecipeBookType::Furnace,
                    RecipeBookType::BlastFurnace,
                    RecipeBookType::Smoker,
                ][words[1].parse::<usize>().unwrap()];
                book.set_book_setting(ty, words[2] == "true", words[3] == "true");
            }
            "initial" => {
                let (settings, add) = book.initial_packets(&manager);
                events.push(format!("PKT settings {}", hex(&settings)));
                events.push(format!("PKT add {}", hex(&add)));
            }
            other => panic!("unknown op {other}"),
        }
        let mut ours = vec![
            format!("known {}", sorted_ids(book.known())),
            format!("highlight {}", sorted_ids(book.highlighted())),
            format!("settings {}", hex(book.book_settings())),
        ];
        ours.extend(events);
        let (mut ours, mut expected) = (ours, expected);
        if words[0] == "initial" {
            for list in [&mut ours, &mut expected] {
                for l in list.iter_mut() {
                    if let Some(h) = l.strip_prefix("PKT add ") {
                        *l = format!("PKT add {}", normalized_add(h));
                    }
                }
            }
        }
        assert_eq!(ours, expected, "op #{op_no}: {op}");
    }
    eprintln!("add packets: {adds}, remove packets: {removes}");
    assert!(adds > 20 && removes > 5);
    stem.close();
}
